// Ruby-free port of test/prism/errors_test.rb — see UNI.md.
//
// Two halves, ported differently:
//
// - The ~300 fixture files (test/errors/**/*.txt): each is source text with
//   caret annotations rendered inline, generated by (and checked against)
//   Prism::Result#errors_format (lib/prism/parse_result/errors.rb) - a
//   Ruby-only formatter with no JS port. Rather than write a second,
//   independent parser for that caret format (fragile - the format has
//   several interacting branches for single-line vs. multi-line error
//   spans), support/errors-format.js ports the *renderer* itself, and this
//   test re-renders each fixture from target_js_uni's own errors and
//   compares the text byte-for-byte against the fixture - the same
//   round-trip property the Ruby test itself relies on (it's generated by,
//   and tested against, that exact renderer).
// - A handful of standalone assertions (not fixture-driven) that check
//   specific error/field behavior directly - ported as direct calls below.

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, relative } from "node:path";
import { fileURLToPath } from "node:url";

import { uniEnvelope, rawEnvelope } from "./support/uni-envelope.mjs";
import { findNode, lineForOffset } from "./support/build-options.mjs";
import { errorsFormat, stripCarets } from "./support/errors-format.mjs";

const ERRORS_DIR = join(fileURLToPath(new URL(".", import.meta.url)), "..", "fixtures", "potch_errors");
const SYNTAX_VERSIONS = ["3.3", "3.4", "4.0", "4.1"];

function versionsFor(relPath) {
  const parts = relPath.split("/");
  if (parts.length === 1) return SYNTAX_VERSIONS;
  const [start, stop] = parts[0].split("-");
  const startIdx = SYNTAX_VERSIONS.indexOf(start);
  if (startIdx === -1) return SYNTAX_VERSIONS;
  if (stop) return SYNTAX_VERSIONS.slice(startIdx, SYNTAX_VERSIONS.indexOf(stop) + 1);
  return SYNTAX_VERSIONS.slice(startIdx);
}

function collectErrorFixtures(dir, base = dir) {
  const out = [];
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) out.push(...collectErrorFixtures(full, base));
    else if (entry.endsWith(".txt")) out.push(relative(base, full).split("\\").join("/"));
  }
  return out;
}

for (const relPath of collectErrorFixtures(ERRORS_DIR)) {
  const versions = versionsFor(relPath);
  const version = versions[versions.length - 1];

  test(`error fixture: ${relPath} (${version})`, () => {
    const fixtureText = readFileSync(join(ERRORS_DIR, relPath), "utf8");
    const source = stripCarets(fixtureText);

    const envelope = rawEnvelope(source, { version });
    assert.ok(envelope.errors.length > 0, "expected at least one error");

    const rendered = errorsFormat(source, envelope.errors, envelope.offsets);
    assert.equal(rendered, fixtureText);
  });
}

test("=begin/=end blocks ending in various EOF terminators still parse", () => {
  const source = "=begin\n=end\n=begin\n=end\0\n=begin\n=end\x04\n=begin\n=end\x1a\n";
  assert.equal(uniEnvelope(source).errors.length, 0);
});

test("unterminated construct at EOF reports the last line", () => {
  assert.equal(lineOfFirstError("foo("), 1);
  assert.equal(lineOfFirstError("foo(\n"), 1);
  assert.equal(lineOfFirstError("foo(\n\n\n\n\n"), 5);
});

function lineOfFirstError(source) {
  const { errors, offsets, start_line: startLine } = rawEnvelope(source);
  return lineForOffset(offsets, startLine, errors[0].start);
}

// StringNode#closing_loc is never nil here, even when unterminated - Prism
// synthesizes a zero-length location at EOF (mirrors Ruby's
// `closing_loc&.slice` being "", not raising on nil).
function isEmptyLocation(loc) {
  return loc != null && loc.start === loc.end;
}

test("unterminated single-quoted string closes with an empty closing", () => {
  const node = firstStatement("'hello");
  assert.equal(node.unescaped, "hello");
  assert.ok(isEmptyLocation(node.closing_loc));
});

test("unterminated interpolated string closes with an empty closing", () => {
  const node = firstStatement('"hello');
  assert.equal(node.unescaped, "hello");
  assert.ok(isEmptyLocation(node.closing_loc));
});

test("unterminated empty string closes with empty unescaped and closing", () => {
  const node = firstStatement('"');
  assert.equal(node.unescaped, "");
  assert.ok(isEmptyLocation(node.closing_loc));
});

test("an invalid message name writes an empty symbol", () => {
  const node = firstStatement("+.@foo,+=foo");
  assert.equal(node.write_name, "");
});

test("regexp encoding option mismatch is reported, matching encoding is not", () => {
  // UTF-8 char with ASCII-8BIT modifier / EUC-JP modifier / Windows-31J modifier
  for (const source of ["/\u0202/n", "/\u0202/e", "/\u0202/s"]) {
    const { errors } = uniEnvelope(source);
    assert.ok(
      errors.some((e) => e.type === "regexp_encoding_option_mismatch"),
      `expected a regexp_encoding_option_mismatch error for ${JSON.stringify(source)}`,
    );
  }

  // UTF-8 char with UTF-8 modifier: no error.
  assert.deepStrictEqual(uniEnvelope("/\u0202/u").errors, []);
});

test("an incomplete def has an empty end_keyword_loc", () => {
  const node = firstStatement("def f; 123");
  assert.ok(isEmptyLocation(node.end_keyword_loc));
});

function firstStatement(source) {
  const { ast } = uniEnvelope(source);
  return ast.statements.body[0];
}
